CREATE TYPE "PaymentIntentStatus" AS ENUM ('DRAFT','PENDING_APPROVAL','READY','PROCESSING','PAID','FAILED','CANCELLED','REFUNDED','PARTIALLY_REFUNDED');
CREATE TYPE "PaymentMode" AS ENUM ('TOKEN','FULL','BALANCE','CUSTOM_APPROVED_AMOUNT');
CREATE TYPE "PaymentProvider" AS ENUM ('RAZORPAY');
CREATE TYPE "PaymentProviderEventStatus" AS ENUM ('RECEIVED','PROCESSED','FAILED','IGNORED');
CREATE TYPE "RefundStatus" AS ENUM ('REQUESTED','APPROVED','PROCESSING','SUCCEEDED','FAILED','CANCELLED');
CREATE TYPE "IdempotencyStatus" AS ENUM ('PROCESSING','SUCCEEDED','FAILED');
CREATE TYPE "ReconciliationStatus" AS ENUM ('PENDING','MATCHED','MISMATCH','INVESTIGATE');
CREATE TYPE "CheckoutEnquiryStatus" AS ENUM ('RECEIVED','PAYMENT_PENDING_APPROVAL','PAYMENT_READY','CANCELLED');
CREATE TYPE "CheckoutPlanKey" AS ENUM ('SILVER','GOLD','PLATINUM','CUSTOM');
CREATE TYPE "PaymentCaptureMode" AS ENUM ('AUTO','MANUAL');

CREATE TABLE "PaymentIntent" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "customerId" TEXT, "enquiryId" TEXT, "orderId" TEXT, "status" "PaymentIntentStatus" NOT NULL DEFAULT 'DRAFT', "currency" TEXT NOT NULL DEFAULT 'INR', "amountMinor" BIGINT NOT NULL, "purpose" TEXT NOT NULL, "paymentMode" "PaymentMode" NOT NULL, "totalOrderAmountMinor" BIGINT NOT NULL, "approvedAmountMinor" BIGINT NOT NULL, "amountAlreadyPaidMinor" BIGINT NOT NULL DEFAULT 0, "balanceDueMinor" BIGINT NOT NULL, "provider" "PaymentProvider", "providerOrderId" TEXT, "providerPaymentId" TEXT, "expiresAt" TIMESTAMP(3), "captureMode" "PaymentCaptureMode", "createdById" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "PaymentIntent_pkey" PRIMARY KEY ("id"), CONSTRAINT "payment_amounts_consistent" CHECK ("currency" = 'INR' AND "amountMinor" > 0 AND "totalOrderAmountMinor" >= 0 AND "approvedAmountMinor" >= 0 AND "amountAlreadyPaidMinor" >= 0 AND "balanceDueMinor" = "approvedAmountMinor" - "amountAlreadyPaidMinor" AND "approvedAmountMinor" <= "totalOrderAmountMinor" AND "amountAlreadyPaidMinor" <= "approvedAmountMinor" AND "amountMinor" <= "balanceDueMinor" AND ("provider" IS NOT NULL OR ("providerOrderId" IS NULL AND "providerPaymentId" IS NULL))));
CREATE TABLE "PaymentIdempotencyKey" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "operation" TEXT NOT NULL, "idempotencyKey" TEXT NOT NULL, "requestFingerprint" TEXT NOT NULL, "status" "IdempotencyStatus" NOT NULL DEFAULT 'PROCESSING', "responseReference" TEXT, "expiresAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "PaymentIdempotencyKey_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PaymentProviderEvent" ("id" TEXT NOT NULL, "organizationId" TEXT, "provider" "PaymentProvider" NOT NULL, "externalEventId" TEXT NOT NULL, "eventType" TEXT NOT NULL, "signatureVerified" BOOLEAN NOT NULL DEFAULT false, "receivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "processedAt" TIMESTAMP(3), "processingStatus" "PaymentProviderEventStatus" NOT NULL DEFAULT 'RECEIVED', "paymentIntentId" TEXT, "providerPaymentId" TEXT, "providerOrderId" TEXT, "amountMinor" BIGINT, "currency" TEXT, "payloadHash" TEXT NOT NULL, "errorCode" TEXT, CONSTRAINT "PaymentProviderEvent_pkey" PRIMARY KEY ("id"), CONSTRAINT "provider_event_verified_before_processed" CHECK ("processingStatus" <> 'PROCESSED' OR "signatureVerified" = true));
CREATE TABLE "CheckoutEnquiry" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "idempotencyKey" TEXT NOT NULL, "requestFingerprint" TEXT NOT NULL, "status" "CheckoutEnquiryStatus" NOT NULL DEFAULT 'RECEIVED', "planKey" "CheckoutPlanKey" NOT NULL, "designSlug" TEXT, "designName" TEXT, "designOccasion" TEXT, "designStyle" TEXT, "customerName" TEXT NOT NULL, "customerEmail" TEXT NOT NULL, "customerPhone" TEXT NOT NULL, "customerWhatsapp" TEXT, "address1" TEXT NOT NULL, "address2" TEXT, "city" TEXT NOT NULL, "state" TEXT NOT NULL, "pincode" TEXT NOT NULL, "country" TEXT NOT NULL, "eventDate" TEXT, "eventLocation" TEXT, "notes" TEXT, "contactEmail" BOOLEAN NOT NULL DEFAULT false, "contactSms" BOOLEAN NOT NULL DEFAULT false, "marketing" BOOLEAN NOT NULL DEFAULT false, "briefSubmitted" BOOLEAN NOT NULL DEFAULT false, "approvedById" TEXT, "approvedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "CheckoutEnquiry_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PaymentProviderConfiguration" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "provider" "PaymentProvider" NOT NULL, "captureMode" "PaymentCaptureMode", "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "PaymentProviderConfiguration_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Refund" ("id" TEXT NOT NULL, "paymentIntentId" TEXT NOT NULL, "amountMinor" BIGINT NOT NULL, "status" "RefundStatus" NOT NULL DEFAULT 'REQUESTED', "providerRefundId" TEXT, "idempotencyKey" TEXT NOT NULL, "reason" TEXT, "requestedById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Refund_pkey" PRIMARY KEY ("id"), CONSTRAINT "refund_amount_nonnegative" CHECK ("amountMinor" > 0));
CREATE TABLE "PaymentReconciliation" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "paymentIntentId" TEXT NOT NULL, "status" "ReconciliationStatus" NOT NULL DEFAULT 'PENDING', "reasonCode" TEXT, "checkedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "PaymentReconciliation_pkey" PRIMARY KEY ("id"));

CREATE UNIQUE INDEX "PaymentIdempotencyKey_organizationId_operation_idempotencyKey_key" ON "PaymentIdempotencyKey"("organizationId","operation","idempotencyKey");
CREATE UNIQUE INDEX "PaymentProviderEvent_provider_externalEventId_key" ON "PaymentProviderEvent"("provider","externalEventId");
CREATE UNIQUE INDEX "PaymentIntent_enquiryId_key" ON "PaymentIntent"("enquiryId");
CREATE UNIQUE INDEX "PaymentIntent_provider_providerOrderId_key" ON "PaymentIntent"("provider","providerOrderId");
CREATE UNIQUE INDEX "PaymentIntent_provider_providerPaymentId_key" ON "PaymentIntent"("provider","providerPaymentId");
CREATE UNIQUE INDEX "CheckoutEnquiry_organizationId_idempotencyKey_key" ON "CheckoutEnquiry"("organizationId","idempotencyKey");
CREATE UNIQUE INDEX "PaymentProviderConfiguration_organizationId_provider_key" ON "PaymentProviderConfiguration"("organizationId","provider");
CREATE UNIQUE INDEX "Refund_idempotencyKey_key" ON "Refund"("idempotencyKey");
CREATE INDEX "PaymentIntent_organizationId_status_createdAt_idx" ON "PaymentIntent"("organizationId","status","createdAt");
CREATE INDEX "PaymentIntent_orderId_idx" ON "PaymentIntent"("orderId");
CREATE INDEX "CheckoutEnquiry_organizationId_status_createdAt_idx" ON "CheckoutEnquiry"("organizationId","status","createdAt");
CREATE INDEX "PaymentProviderEvent_organizationId_processingStatus_receivedAt_idx" ON "PaymentProviderEvent"("organizationId","processingStatus","receivedAt");
CREATE INDEX "PaymentProviderEvent_providerPaymentId_idx" ON "PaymentProviderEvent"("providerPaymentId");
CREATE INDEX "Refund_paymentIntentId_status_createdAt_idx" ON "Refund"("paymentIntentId","status","createdAt");
CREATE INDEX "PaymentReconciliation_organizationId_status_checkedAt_idx" ON "PaymentReconciliation"("organizationId","status","checkedAt");
CREATE INDEX "PaymentReconciliation_paymentIntentId_checkedAt_idx" ON "PaymentReconciliation"("paymentIntentId","checkedAt");

