ALTER TABLE "PaymentProviderEvent" ADD CONSTRAINT "PaymentProviderEvent_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE SET NULL ON UPDATE CASCADE;
